require_once __DIR__.'/lib/auth.php';requireAuth();if($_SERVER['REQUEST_METHOD']!=='POST'||!verifyCsrf($_POST['csrf']??'')){http_response_code(403);exit('Invalid request.');}$pdo=db();$tables=['users','sources','candidates','jobs','integrations','password_reset_tokens','wishlist_profiles','wishlist_items','email_batches','email_recipients'];$filename='resumeiq-backup-'.date('Ymd-His').'.sql';header('Content-Type: application/sql; charset=utf-8');header('Content-Disposition: attachment; filename="'.$filename.'"');header('X-Content-Type-Options: nosniff');echo "-- ResumeIQ database backup\n-- Created ".date(DATE_ATOM)."\nSET NAMES utf8mb4;\nSET FOREIGN_KEY_CHECKS=0;\n\n";foreach($tables as $table){$create=$pdo->query("SHOW CREATE TABLE `$table`")->fetch(PDO::FETCH_NUM);if(!$create)continue;echo "DROP TABLE IF EXISTS `$table`;\n".$create[1].";\n\n";$rows=$pdo->query("SELECT * FROM `$table`");while($row=$rows->fetch(PDO::FETCH_ASSOC)){$columns=array_map(fn($c)=>'`'.str_replace('`','``',$c).'`',array_keys($row));$values=array_map(fn($v)=>$v===null?'NULL':$pdo->quote((string)$v),array_values($row));echo "INSERT INTO `$table` (".implode(',',$columns).") VALUES (".implode(',',$values).");\n";}echo "\n";}echo "SET FOREIGN_KEY_CHECKS=1;\n";
